package contractgen

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"
)

// GoHeader starts every generated Go file; go vet and the linters recognize it.
const GoHeader = "// Code generated by contractgen from %s. DO NOT EDIT.\n// Regenerate: %s\n\n"

// Regenerate is the command that rewrites every generated file.
const Regenerate = UpdateEnv + "=1 go test ./internal/contractgen/ (in backend/)"

// Go renders the doc's types as one Go file of package pkg.
func (d *Doc) Go(pkg string) ([]byte, error) {
	var body bytes.Buffer
	imports := map[string]bool{}
	kindOverride := d.kindTypes()
	for _, name := range d.Names() {
		s := d.Defs[name]
		comment(&body, "", name, s.Description)
		if s.Type == "string" {
			fmt.Fprintf(&body, "type %s string\n\n", name)
			fmt.Fprintf(&body, "// %s values.\nconst (\n", name)
			for _, v := range s.Enum {
				fmt.Fprintf(&body, "\t%s%s %s = %q\n", name, goName(v), name, v)
			}
			body.WriteString(")\n\n")
			fmt.Fprintf(&body, "// %sValues lists every %s.\nvar %sValues = []%s{", name, name, name, name)
			for i, v := range s.Enum {
				if i > 0 {
					body.WriteString(", ")
				}
				fmt.Fprintf(&body, "%s%s", name, goName(v))
			}
			body.WriteString("}\n\n")
			continue
		}
		fmt.Fprintf(&body, "type %s struct {\n", name)
		for _, p := range s.Order {
			ps := s.Properties[p]
			req := s.isRequired(p)
			typ, err := d.goType(ps, req, imports)
			if err != nil {
				return nil, fmt.Errorf("%s.%s: %w", name, p, err)
			}
			if kt, ok := kindOverride[name]; ok && p == "kind" {
				typ = kt
			}
			if ps.Description != "" {
				for _, l := range wrap(ps.Description, 110) {
					fmt.Fprintf(&body, "\t// %s\n", l)
				}
			}
			tag := p
			if !req {
				tag += ",omitempty"
			}
			fmt.Fprintf(&body, "\t%s %s `json:\"%s\"`\n", goName(p), typ, tag)
		}
		body.WriteString("}\n\n")
	}
	for _, u := range d.Unions {
		d.goUnion(&body, u)
	}
	var out bytes.Buffer
	fmt.Fprintf(&out, GoHeader, d.Source, Regenerate)
	fmt.Fprintf(&out, "package %s\n\n", pkg)
	if len(imports) > 0 {
		out.WriteString("import (\n")
		for _, imp := range sortedKeys(imports) {
			fmt.Fprintf(&out, "\t%q\n", imp)
		}
		out.WriteString(")\n\n")
	}
	out.Write(body.Bytes())
	return format.Source(out.Bytes())
}

func (d *Doc) goUnion(b *bytes.Buffer, u Union) {
	fmt.Fprintf(b, "// %s is the kind of a %s: it selects the payload type of its data.\ntype %s string\n\n",
		u.KindType, u.Envelope, u.KindType)
	fmt.Fprintf(b, "// %s values.\nconst (\n", u.KindType)
	for _, k := range u.Kinds {
		fmt.Fprintf(b, "\t%s%s %s = %q\n", u.GoPrefix, goName(k.Kind), u.KindType, k.Kind)
	}
	b.WriteString(")\n\n")
	fmt.Fprintf(b, "// %sInfo describes one %s: its payload type and how it travels.\n", u.KindType, u.KindType)
	fmt.Fprintf(b, "type %sInfo struct {\n\tKind %s\n", u.KindType, u.KindType)
	b.WriteString("\t// Ephemeral: delivered live, never written to the log, no seq.\n\tEphemeral bool\n")
	b.WriteString("\t// Sidecar: the host forwards it to the sidecar's stdin.\n\tSidecar bool\n")
	b.WriteString("\t// New returns a pointer to a zero payload.\n\tNew func() any\n}\n\n")
	fmt.Fprintf(b, "// %sInfos lists every %s in contract order.\nvar %sInfos = []%sInfo{\n", u.KindType,
		u.KindType, u.KindType, u.KindType)
	for _, k := range u.Kinds {
		fmt.Fprintf(b, "\t{Kind: %s%s, Ephemeral: %t, Sidecar: %t, New: func() any { return new(%s) }},\n",
			u.GoPrefix, goName(k.Kind), k.Ephemeral, k.Sidecar, k.Payload)
	}
	b.WriteString("}\n\n")
}

func (d *Doc) goType(s *Schema, required bool, imports map[string]bool) (string, error) {
	switch {
	case s.Ref != "":
		name, err := d.resolve(s.Ref)
		if err != nil {
			return "", err
		}
		if !required && d.Defs[name].Type == "object" {
			return "*" + name, nil
		}
		return name, nil
	case s.Type == "array":
		t, err := d.goType(s.Items, true, imports)
		return "[]" + t, err
	case s.Type == "object":
		t, err := d.goType(s.Values, true, imports)
		return "map[string]" + t, err
	case s.Type == "string" && s.Format == "date-time":
		imports["time"] = true
		if !required {
			return "*time.Time", nil
		}
		return "time.Time", nil
	case s.Type == "string":
		return "string", nil
	case s.Type == "integer" && s.Format == "int64":
		return "int64", nil
	case s.Type == "integer":
		return "int", nil
	case s.Type == "number":
		// An optional number is a pointer: absent and zero mean different things (a cost not reported is not free).
		if !required {
			return "*float64", nil
		}
		return "float64", nil
	case s.Type == "boolean":
		return "bool", nil
	case s.Type == "":
		imports["encoding/json"] = true
		return "json.RawMessage", nil
	}
	return "", fmt.Errorf("unsupported type %q", s.Type)
}

// comment writes a doc comment that starts with the declared name, as golint wants.
func comment(b *bytes.Buffer, indent, name, desc string) {
	text := name + " is part of the contract."
	if desc != "" {
		text = name + ": " + desc
	}
	for _, l := range wrap(text, 110) {
		fmt.Fprintf(b, "%s// %s\n", indent, l)
	}
}

// wrap breaks text into lines of at most width runes at spaces.
func wrap(text string, width int) []string {
	var lines []string
	var cur strings.Builder
	for _, w := range strings.Fields(text) {
		if cur.Len() > 0 && cur.Len()+1+len(w) > width {
			lines = append(lines, cur.String())
			cur.Reset()
		}
		if cur.Len() > 0 {
			cur.WriteByte(' ')
		}
		cur.WriteString(w)
	}
	if cur.Len() > 0 {
		lines = append(lines, cur.String())
	}
	return lines
}
